from common import *
P=R/'projects/game-math-bounds-transform-v2';H=P/'production/concept-fit-v2';T=read(H/'timeline.json');D=P/'publishing/revisions/concept-fit-v2';D.mkdir(parents=True,exist_ok=True)
en=['From connections to object size and rotated bounds','A rounded surface and a calculation sphere','Enclose the head and limbs separately','Sphere tests use distance from the center','Distinguish a sphere surface from its interior','Does double radius mean double size?','A spherical bound around an elongated body','Extending arms changes the bounds','Data for an axis-aligned box','Choose minimum and maximum on each axis','Build a box from five points','Begin box overlap with one-dimensional intervals','Place and resize a building','Box overlap is not object contact','Broad-phase candidates and precise tests','Update the bounds after rotation','Rotating only minimum and maximum is incorrect','Distinguish object rotation from camera motion','Separate model angles from observed game images','View a fixed building from another direction','Why half-extents need absolute values','Transform a center and half-extents efficiently','Recalculate bounds after a height change','Compare structural and articulated bounds','Connect the calculations through two problems']
